#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    // Multiset via frequency map plus min/max heaps with lazy deletion.
    unordered_map<ll, int> freq;
    freq.reserve(1 << 18);
    priority_queue<ll, vector<ll>, greater<ll>> lo;
    priority_queue<ll> hi;
    size_t live = 0;
    char op[8];
    ll x;
    string out;
    out.reserve(n * 20);
    for (int i = 0; i < n; i++) {
        scanf("%7s %lld", op, &x);
        if (op[1] == 'u') { freq[x]++; live++; lo.push(x); hi.push(x); }
        else { freq[x]--; live--; }
        while (!lo.empty() && freq[lo.top()] == 0) lo.pop();
        while (!hi.empty() && freq[hi.top()] == 0) hi.pop();
        out += to_string(live ? lo.top() * hi.top() : 0LL);
        out += '\n';
    }
    fputs(out.c_str(), stdout);
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));
        int n = (int) readLong(in);
        // Multiset via frequency map plus min/max heaps with lazy deletion.
        HashMap<Long, Integer> freq = new HashMap<>();
        PriorityQueue<Long> lo = new PriorityQueue<>();
        PriorityQueue<Long> hi = new PriorityQueue<>(Comparator.reverseOrder());
        long live = 0;
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < n; i++) {
            boolean push = readOp(in);
            long x = readLong(in);
            if (push) { freq.merge(x, 1, Integer::sum); live++; lo.add(x); hi.add(x); }
            else { freq.merge(x, -1, Integer::sum); live--; }
            while (!lo.isEmpty() && freq.getOrDefault(lo.peek(), 0) == 0) lo.poll();
            while (!hi.isEmpty() && freq.getOrDefault(hi.peek(), 0) == 0) hi.poll();
            out.append(live > 0 ? lo.peek() * hi.peek() : 0).append('\n');
        }
        System.out.print(out);
    }

    // Reads "push" or "pop" and returns true for push.
    static boolean readOp(DataInputStream in) throws IOException {
        int b = in.read();
        while (b < 'a' || b > 'z') b = in.read();
        int second = in.read();
        while (b >= 'a' && b <= 'z') b = in.read();
        return second == 'u';
    }

    static long readLong(DataInputStream in) throws IOException {
        int b = in.read();
        while (b != '-' && (b < '0' || b > '9')) b = in.read();
        boolean neg = false;
        if (b == '-') { neg = true; b = in.read(); }
        long r = 0;
        while (b >= '0' && b <= '9') { r = r * 10 + (b - '0'); b = in.read(); }
        return neg ? -r : r;
    }
}

package main

import (
	"bufio"
	"container/heap"
	"os"
	"strconv"
)

type minHeap []int64

func (h minHeap) Len() int           { return len(h) }
func (h minHeap) Less(i, j int) bool { return h[i] < h[j] }
func (h minHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *minHeap) Push(x any)        { *h = append(*h, x.(int64)) }
func (h *minHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<16)
	out := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer out.Flush()
	word := func() []byte {
		b, _ := in.ReadByte()
		for b == ' ' || b == '\n' || b == '\r' || b == '\t' {
			b, _ = in.ReadByte()
		}
		var w []byte
		for b != ' ' && b != '\n' && b != '\r' && b != '\t' && b != 0 {
			w = append(w, b)
			var err error
			if b, err = in.ReadByte(); err != nil {
				break
			}
		}
		return w
	}
	n, _ := strconv.Atoi(string(word()))
	// Multiset via frequency map plus min/max heaps (max heap stores negatives) with lazy deletion.
	freq := make(map[int64]int)
	lo, hi := &minHeap{}, &minHeap{}
	live := 0
	for i := 0; i < n; i++ {
		op := word()
		x, _ := strconv.ParseInt(string(word()), 10, 64)
		if op[1] == 'u' {
			freq[x]++
			live++
			heap.Push(lo, x)
			heap.Push(hi, -x)
		} else {
			freq[x]--
			live--
		}
		for lo.Len() > 0 && freq[(*lo)[0]] == 0 {
			heap.Pop(lo)
		}
		for hi.Len() > 0 && freq[-(*hi)[0]] == 0 {
			heap.Pop(hi)
		}
		var p int64
		if live > 0 {
			p = (*lo)[0] * -(*hi)[0]
		}
		out.WriteString(strconv.FormatInt(p, 10))
		out.WriteByte('\n')
	}
}
